//
// 重新生成（仓库根执行；输出即下面 `base64` 的字面量）：
//
//   python3 - <<'PY'
//   import base64, pathlib
//   for n in "idle waiting puzzled crying terrified angry coquettish cute pleasing knocking face-palm tongue-out".split():
//       print(f'        "{n}": "{base64.b64encode(pathlib.Path("shared/pet/stickers", n + ".png").read_bytes()).decode()}",')
//   PY

import UIKit

enum PetStickerImages {

    /// 文件名（不含 `.png`）→ 280×280 透明底 PNG 的 base64。
    static let base64: [String: String] = [
        "idle": "",
        "waiting": "",
        "puzzled": "",
        "crying": "",
        "terrified": "",
        "angry": "",
        "coquettish": "",
        "cute": "",
        "pleasing": "",
        "knocking": "",
        "face-palm": "",
        "tongue-out": "",
    ]

    /// base64 → `UIImage`；缺条目或数据损坏返回 nil（调用方提示缺失，不画占位字形）。
    static func image(named name: String) -> UIImage? {
        guard let text = base64[name], let data = Data(base64Encoded: text) else { return nil }
        return UIImage(data: data)
    }
}
